package com.pousada.api;

import com.pousada.service.RoomService;
import io.javalin.Javalin;
import java.sql.SQLException;

public class RoomEndpoints {
    public static void register(Javalin app) {
        app.get("/rooms", ctx -> {
            try {
                var rooms = new RoomService().getAllRooms();
                var response = rooms.stream().map(r -> new Object() {
                    public final int number = r.number;
                    public final String type = r.type;
                    public final int capacity = r.capacity;
                    public final String nightlyRate = String.format("%.2f", r.nightlyRate);
                }).toArray();
                ctx.json(response);
            } catch (SQLException e) {
                ctx.status(500).json(new Object() {
                    public final String error = "DATABASE_ERROR";
                    public final String message = e.getMessage();
                });
            }
        });
