    private static Object mapReservationResponse(Reservation res) {
        return new Object() {
            public final int id = res.id;
            public final int roomNumber = res.roomNumber;
            public final String guestName = res.guestName;
            public final String guestEmail = res.guestEmail;
            public final String guestCpf = res.guestCpf;
            public final String checkIn = res.checkIn.toString();
            public final String checkOut = res.checkOut.toString();
            public final int guests = res.guests;
            public final String ratePlan = res.ratePlan;
            public final int nights = res.nights;
            public final String subtotal = String.format("%.2f", res.subtotal);
            public final String discount = String.format("%.2f", res.discount);
            public final String total = String.format("%.2f", res.total);
            public final String status = res.status;
            public final String amountPaid = String.format("%.2f", res.amountPaid);
            public final Object refund = res.refund == null ? null : String.format("%.2f", res.refund);
        };
    }

    private static Object createVoucherResponse(Reservation res, String voucher) {
        return new Object() {
            public final String title = "Comprovante de reserva";
            public final int reservationId = res.id;
            public final String guestName = res.guestName;
            public final String guestCpf = res.guestCpf;
            public final int roomNumber = res.roomNumber;
            public final String roomType = res.ratePlan;
            public final String checkIn = res.checkIn.toString();
            public final String checkOut = res.checkOut.toString();
            public final int nights = res.nights;
            public final String subtotal = String.format("%.2f", res.subtotal);
            public final String discount = String.format("%.2f", res.discount);
            public final String total = String.format("%.2f", res.total);
        };
    }

    private static Object createError(String code, String message) {
        return new Object() {
            public final String error = code;
            public final String message = message;
        };
    }

    private static void handleError(io.javalin.http.Context ctx, String errorCode) {
        String message = switch (errorCode) {
            case "ROOM_NOT_FOUND" -> "Room not found";
            case "RESERVATION_NOT_FOUND" -> "Reservation not found";
            case "ROOM_UNAVAILABLE" -> "Room is unavailable for the selected dates";
            case "OPERATION_NOT_ALLOWED" -> "This operation is not allowed for the current reservation state";
            case "CAPACITY_EXCEEDED" -> "Too many guests for this room";
            case "INVALID_REQUEST" -> "Invalid request";
            default -> "An error occurred";
        };

        int status = switch (errorCode) {
            case "ROOM_NOT_FOUND", "RESERVATION_NOT_FOUND" -> 404;
            case "ROOM_UNAVAILABLE", "OPERATION_NOT_ALLOWED" -> 409;
            case "CAPACITY_EXCEEDED" -> 422;
            default -> 400;
        };

        ctx.status(status).json(createError(errorCode, message));
    }

    private static int getIntField(ObjectNode body, String field) throws IllegalArgumentException {
        if (!body.has(field)) {
            throw new IllegalArgumentException("INVALID_REQUEST");
        }
        return body.get(field).asInt();
    }

    private static String getStringField(ObjectNode body, String field) throws IllegalArgumentException {
        if (!body.has(field)) {
            throw new IllegalArgumentException("INVALID_REQUEST");
        }
        return body.get(field).asText();
    }

    private static LocalDate parseDate(String dateStr) throws DateTimeParseException {
        return LocalDate.parse(dateStr);
    }
}

