17	    @Override
18	    public boolean isValid(LocalDate checkIn, LocalDate checkOut, int guests, String companyCode, Room room) {
19	        return guests >= 1 && checkIn.isBefore(checkOut) && DISCOUNTS.containsKey(companyCode);
20	    }
