23	    public PriceCalculation calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) {
24	        BigDecimal subtotal = calculateSubtotal(room, checkIn, checkOut);
25	        Double discountPercent = DISCOUNTS.get(companyCode);
26	        BigDecimal discount = Money.percent(subtotal, discountPercent);
27	        BigDecimal total = Money.subtract(subtotal, discount);
28	        return new PriceCalculation(subtotal, discount, total);
29	    }
