31	    private BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
32	        BigDecimal total = BigDecimal.ZERO;
33	        LocalDate current = checkIn;
34	        while (current.isBefore(checkOut)) {
35	            BigDecimal nightlyRate = room.nightlyRate;
36	            if (DateUtil.isHighSeason(current)) {
37	                nightlyRate = Money.multiply(nightlyRate, BigDecimal.valueOf(1.2));
38	            }
39	            total = Money.add(total, nightlyRate);
40	            current = current.plusDays(1);
